   160	    Order payNewOrder(List<RequestItem> items, String tx) {
   161	        Order order = app.checkout().register(req(items, "STORE_PICKUP", null, "PIX", 1, "SILVER", "SOUTH"));
   162	        return app.orders().confirmPayment(order.id(), tx, NOW.plusSeconds(60));
