   168	                "SILVER", "SOUTH"));
   169	        Order paid = app.orders().confirmPayment(order.id(), "TX-1", NOW.plusSeconds(60));
   170	        Order again = app.orders().confirmPayment(order.id(), "TX-1", NOW.plusSeconds(120));
   171	        assertEquals(OrderStatus.PAID, paid.status());
   172	        assertEquals(OrderStatus.PAID, again.status());
   173	        assertEquals(0, app.queries().product("MOC-001").stock());
   174	        assertEquals(new BigDecimal("3.20"), app.queries().customer("12345678909").creditBalance());
   175	        assertEquals(1, app.queries().notifications("12345678909").size());
   176	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, assertThrows(DomainException.class,
   177	                () -> app.orders().confirmPayment(order.id(), "TX-2", NOW)).code());
