   188	        assertEquals(ErrorCode.INSUFFICIENT_STOCK, e.code());
   189	        assertEquals(409, e.status());
   190	        assertEquals(OrderStatus.CANCELLED, app.orders().get(b.id()).status());
   191	        assertEquals(ErrorCode.INSUFFICIENT_STOCK, assertThrows(DomainException.class,
