    11	/** Montagem dos serviços. */
    12	public record Application(CheckoutService checkout, OrderService orders, QueryService queries) {
    13	    public static Application create(Store store, CarrierClient carrier, Clock clock) {
    14	        CheckoutCalculator calculator = new CheckoutCalculator(ShippingOptions.standard(carrier),
    15	                Coupons.standard(), PaymentMethods.standard());
    16	        // O estoque vem primeiro: é o único que pode recusar o pagamento.
    17	        List<OrderEventListener> listeners = List.of(new StockListener(), new CreditListener(),
    18	                new NotificationListener());
    19	        return new Application(new CheckoutService(store, calculator, clock),
    20	                new OrderService(store, listeners), new QueryService(store));
    21	    }
