    52	/** Implementação em memória (usada nos testes). Não desfaz alterações em caso de erro. */
    53	public class MemoryStore implements Store, Tx {
    54	    private final ReentrantLock lock = new ReentrantLock();
    55	    private final Map<String, Product> products = new LinkedHashMap<>();
    56	    private final Map<String, Order> orders = new LinkedHashMap<>();
    57	    private final Map<String, Customer> customers = new HashMap<>();
    58	    private final List<Notification> notifications = new ArrayList<>();
    59	    private final Map<String, PaymentRepository.PaymentRecord> payments = new HashMap<>();
    60	
    61	    @Override
    62	    public <T> T inTransaction(Function<Tx, T> work) {
    63	        lock.lock();
    64	        try {
    65	            return work.apply(this);
    66	        } finally {
    67	            lock.unlock();
    68	        }
    69	    }
    70	
    71	    @Override
    72	    public ProductRepository products() {
    73	        return new ProductRepository() {
    74	            public Optional<Product> find(String sku) {
    75	                return Optional.ofNullable(products.get(sku));
    76	            }
    77	
    78	            public void insertIfAbsent(Product p) {
    79	                products.putIfAbsent(p.sku(), p);
    80	            }
    81	
    82	            public boolean tryDebit(List<CartItem> items) {
    83	                for (CartItem i : items) {
    84	                    Product p = products.get(i.sku());
    85	                    if (p == null || p.stock() < i.quantity()) {
    86	                        return false;
    87	                    }
    88	                }
    89	                items.forEach(i -> adjust(i.sku(), -i.quantity()));
    90	                return true;
    91	            }
    92	
    93	            public void restore(List<CartItem> items) {
    94	                items.forEach(i -> adjust(i.sku(), i.quantity()));
    95	            }
    96	
    97	            private void adjust(String sku, int delta) {
    98	                Product p = products.get(sku);
    99	                products.put(sku, new Product(p.sku(), p.name(), p.price(), p.weightKg(), p.stock() + delta,
   100	                        p.discontinued()));
   101	            }
   102	        };
   103	    }
   104	
   105	    @Override
   106	    public OrderRepository orders() {
   107	        return new OrderRepository() {
   108	            public void insert(Order order) {
   109	                orders.put(order.id(), order);
   110	            }
   111	
   112	            public Optional<Order> find(String id) {
   113	                return Optional.ofNullable(orders.get(id));
   114	            }
   115	
   116	            public Optional<Order> findForUpdate(String id) {
   117	                return find(id);
   118	            }
   119	
   120	            public void update(Order order) {
   121	                orders.put(order.id(), order);
   122	            }
   123	
   124	            public boolean hasPurchased(String cpf) {
   125	                return orders.values().stream().anyMatch(o -> o.cpf().equals(cpf)
   126	                        && (o.status() == OrderStatus.PAID || o.status() == OrderStatus.SHIPPED
   127	                        || o.status() == OrderStatus.DELIVERED));
   128	            }
   129	        };
   130	    }
   131	
   132	    @Override
   133	    public CustomerRepository customers() {
   134	        return new CustomerRepository() {
   135	            public Optional<Customer> find(String cpf) {
   136	                return Optional.ofNullable(customers.get(cpf));
   137	            }
   138	
   139	            public void ensure(String cpf) {
   140	                customers.putIfAbsent(cpf, new Customer(cpf, Money.ZERO));
   141	            }
   142	
   143	            public void addCredit(String cpf, BigDecimal amount) {
   144	                Customer c = customers.get(cpf);
   145	                customers.put(cpf, new Customer(cpf, c.creditBalance().add(amount)));
   146	            }
   147	        };
   148	    }
   149	
   150	    @Override
   151	    public NotificationRepository notifications() {
   152	        return new NotificationRepository() {
   153	            public void add(String cpf, NotificationType type, String orderId) {
   154	                notifications.add(new Notification(UUID.randomUUID().toString(), type, orderId,
   155	                        NotificationStatus.NEW, cpf));
   156	            }
   157	
   158	            public List<Notification> findByCpf(String cpf) {
   159	                return notifications.stream().filter(n -> n.cpf().equals(cpf)).toList();
   160	            }
   161	
   162	            public Optional<Notification> find(String id) {
   163	                return notifications.stream().filter(n -> n.id().equals(id)).findFirst();
   164	            }
   165	
   166	            public void markRead(String id) {
   167	                for (int i = 0; i < notifications.size(); i++) {
   168	                    Notification n = notifications.get(i);
   169	                    if (n.id().equals(id)) {
   170	                        notifications.set(i, new Notification(n.id(), n.type(), n.orderId(),
   171	                                NotificationStatus.READ, n.cpf()));
   172	                    }
   173	                }
   174	            }
   175	        };
   176	    }
   177	
   178	    @Override
   179	    public PaymentRepository payments() {
   180	        return new PaymentRepository() {
   181	            public Optional<PaymentRepository.PaymentRecord> find(String orderId, String transactionId) {
   182	                return Optional.ofNullable(payments.get(orderId + "|" + transactionId));
   183	            }
   184	
   185	            public void record(String orderId, String transactionId, String errorCode) {
   186	                payments.put(orderId + "|" + transactionId, new PaymentRepository.PaymentRecord(errorCode));
   187	            }
   188	        };
   189	    }
   190	}
