 135	    }
 136	
 137	    @Override
 138	    public ShippingQuote quote(ShippingRequest request) {
 139	        long grams = request.weightKg().movePointRight(3).longValue();
 140	        try {
 141	            CarrierClient.CarrierQuote quote = client.quote(request.zipCode(), grams, carrierService);
 142	            int days = (quote.etaHours() + 23) / 24 + request.region().extraCarrierDays();
 143	            return new ShippingQuote(new BigDecimal(quote.priceCents()).movePointLeft(2), days);
 144	        } catch (CarrierClient.ZipNotServedException e) {
 145	            throw new DomainException(ErrorCode.SHIPPING_METHOD_UNAVAILABLE);
 146	        } catch (CarrierClient.CarrierDownException e) {
 147	            throw new DomainException(ErrorCode.CARRIER_UNAVAILABLE);
 148	        }
 149	    }
 150	
 151	    @Override
 152	    public boolean chargesFreight() {
 153	        return true;
 154	    }
 155	
 156	    @Override
 157	    public boolean clubWaivable() {
 158	        return true;
 159	    }
 160	}
